Ramanujan's formula \eqref{ramanujan formula} can be rephrased in terms of $\mathfrak{F}_{k,1}(x)$ by
\begin{align}\label{k1}
\mathfrak{F}_{k,1}(x)-\frac{1}{x}\mathfrak{F}_{k,1}\left(\frac{1}{x}\right)=\frac{1}{2}\left(\gamma-\log\left(\frac{2\pi}{x}\right)\right)-\frac{1}{2x}\left(\gamma-\log(2\pi x)\right).
\end{align}
Thus Ramanujan understood the importance of such a function. Therefore, it would not be unfair to say that Ramanujan studied Hergltoz-type functions even before Herglotz and Zagier. Further, he went beyond the functional equation to find a surprising intergal representation for this Herglotz-type function which involves the Riemann $\Xi$-function.

\label{N=1 and general k}
Let $\mathfrak{F}_{k,N}(x)$ be defined in \eqref{hhhf}. For any  $k\in\mathbb{N}\cup\{0\}$ and $\mathrm{Re} (x)>0$, the following identity holds:
\begin{align*}
\mathfrak{F}_{k,1}(x)=(-1)^kx^{k-1}\left\{\mathfrak{F}_{k,1}\left(\frac{1}{x}\right)-\mathcal{B}_k(x)\right\},
\end{align*}
where, for $k=0$,
\begin{align*}
\mathcal{B}_k(x):=\frac{x}{2}\left(\log\left(\frac{2\pi}{x}\right)-\gamma\right)+\frac{1}{2}\left(\gamma-\log(2\pi x)\right),
\end{align*}
for $k=1$,
\begin{align*}
\mathcal{B}_k(x):=\frac{1}{6}\left(3\log^2(x)+\pi^2-6\gamma^2-12\gamma_1\right)-\frac{\pi^2}{12}\left(x+\frac{1}{x}\right),
\end{align*}
and for $k\geq2$,
\begin{align*}
\mathcal{B}_k(x):&=\zeta(k)\left(\log(x)-\gamma\right)+\zeta'(k)+(-1)^kx^{1-k}\left((\log(x)+\gamma)\zeta(k)-\zeta'(k)\right)+\frac{(-1)^k}{2x^k}\zeta(k+1)\nonumber\\
&\qquad-\frac{x}{2}\zeta(1+k)+\sum_{j=1}^{k-2}(-1)^{j-1}\zeta(j+1)\zeta(k-j)x^{-j}.
\end{align*}

\label{alphabeta form}
Let $k$ be any natural number greater than 1. Let $\mathrm{Re}(\alpha)>0$ and $\mathrm{Re}(\beta)>0$ such that $\alpha\beta=1$, then the following relation holds:
\begin{align}\label{alphabeta form eqn}
&\alpha^{\frac{1-k}{2}}\left\{(\gamma+\log(\alpha))\zeta(k)-\zeta'(k)+\frac{1}{2\alpha}\zeta(k+1)+\mathfrak{F}_{k,1}(\alpha)\right\}\nonumber\\
&=(-1)^k\beta^{\frac{1-k}{2}}\left\{(\gamma+\log(\beta))\zeta(k)-\zeta'(k)+\frac{1}{2\beta}\zeta(k+1)+\mathfrak{F}_{k,1}(\beta)\right\}\nonumber\\
&\qquad+\sum_{j=1}^{k-2}(-1)^j\zeta(j+1)\zeta(k-j)\alpha^{\frac{1-k+j}{2}}\beta^{-\frac{j}{2}}.
\end{align}

\label{general N and k=0}
Let $N$ be any natural number and $\mathrm{Re} (x)>0$. Then
\begin{align}\label{general N and k=0 eqn}

\mathfrak{F}_{0,N}(x)=\frac{x^{-1/N}}{N}\sideset{}{''}\sum_{j=-(N-1)}^{(N-1)}e^{-\frac{i\pi j}{N}}\mathfrak{F}_{\frac{N-1}{N},\frac{1}{N}}\left(\frac{e^{-\frac{i\pi j}{N}}}{x^{1/N}}\right)-\frac{1}{2}\left(\log\left(\frac{(2\pi)^N}{x}\right)-\gamma\right)+R(N,x),
\end{align}
where
\begin{align}\label{rnx}
R(N,x):=
\begin{cases}
\frac{1}{2x}\left(\log(2\pi x)-\gamma\right), &\mathrm{if} \ N=1\\
-\frac{\pi x^{-1/N}\zeta\left(1-1/N\right)}{N\sin(\pi/N)}-\frac{1}{2x}\zeta(N), &\mathrm{if} \ N>1.
\end{cases}
\end{align}

\label{general theorem}
Let $k,\ N$ be any natural numbers greater $1$. Then for $\mathrm{Re} (x)>0$, we have
\begin{align*}
\mathfrak{F}_{k,N}(x)=\frac{(-1)^k}{N}x^{\frac{k-1}{N}}\sideset{}{''}\sum_{j=-(N-1)}^{N-1}e^{\frac{i\pi j(k-1)}{N}}\mathfrak{F}_{\frac{N+k-1}{N},\frac{1}{N}}\left(\frac{e^{-\frac{i\pi j}{N}}}{x^{1/N}}\right)-\frac{x^{\frac{k-1}{N}}}{N}\mathscr{R}_{N,k}(x),
\end{align*}
where, for $N\nmid (k-1)$ and $N\nmid k$,
\begin{align*}
\mathscr{R}_{N,k}(x)&=\frac{N}{2}x^{\frac{1-k-N}{N}}\zeta(k+N)-\frac{\pi\zeta\left(\frac{N+k-1}{N}\right)}{\sin\left(\frac{\pi}{N}(k-1)\right)}-Nx^{\frac{1-k}{N}}\left(N\zeta'(k)-(\gamma+\log x)\zeta(k)\right)\nonumber\\
&\qquad +N\sum_{j=1}^{\lfloor\frac{k-1}{N}\rfloor}(-1)^j\zeta(1+j)\zeta(k-N)x^{\frac{k-1}{N}+j},
\end{align*}
and, for $N|k$, 
\begin{align*}
\mathscr{R}_{N,k}(x)&=\frac{N}{2}x^{\frac{1-k-N}{N}}\zeta(k+N)-\frac{\pi\zeta\left(\frac{N+k-1}{N}\right)}{\sin\left(\frac{\pi}{N}(k-1)\right)}-Nx^{\frac{1-k}{N}}\left(N\zeta'(k)-(\gamma+\log x)\zeta(k)\right)\nonumber\\
&\quad-\frac{N}{2}(-1)^{\frac{k}{N}}x^{\frac{1}{N}}\zeta\left(\frac{k+N}{N}\right) +N\sum_{j=1}^{\lfloor\frac{k-1}{N}\rfloor}(-1)^j\zeta(1+j)\zeta(k-N)x^{\frac{k-1}{N}+j},
\end{align*}
and, for $N|(k-1)$,
\begin{align*}
\mathscr{R}_{N,k}(x)&=\frac{N}{2}x^{\frac{1-k-N}{N}}\zeta(k+N)+(-1)^{\frac{k-1}{N}}\left((N\gamma-\log x)\zeta\left(\frac{N+k-1}{N}\right)-\zeta'\left(\frac{N+k-1}{N}\right)\right)\nonumber\\
&\quad -Nx^{\frac{1-k}{N}}\left(N\zeta'(k)-(\gamma+\log x)\zeta(k)\right)+N\sum_{j=1}^{\lfloor\frac{k-1}{N}\rfloor-1}(-1)^j\zeta(1+j)\zeta(k-N)x^{\frac{k-1}{N}+j}.
\end{align*}

\label{2.7}
Let $F_{k}(x,\chi)$ be defined in \eqref{Fxi}. Let $\chi(n)$ be a primitive, nonprincipal character modulo $d$. Then $k \in \mathbb{N}\cup\{0\}$ and \textup{Re}$(x)>0$, we have
\begin{align*}
F_{k}(x,\chi)-(-1)^kx^{k-1}F_{k}\left(x,\frac{1}{\chi}\right)=\sum_{j=0}^{k-1}(-x)^{k-j-1}L(1+j,\chi)L(-j+k, \chi).
\end{align*}

\label{2.8}
Let $\chi(n)$ be a primitive, nonprincipal character modulo $d$. Further assume $\mathrm{Re}(\alpha)>0,\ \mathrm{Re}(\beta)>0$ such that $\alpha\beta=1$, then
\begin{align*}
\sqrt{\alpha}F_{0}(\alpha,\chi)&=\sqrt{\beta}F_{0}(\beta,\chi)\nonumber\\
&=-\frac{1}{2\pi}\left(\frac{\pi}{d}\right)^{b+\frac{1}{2}}\int_{0}^{\infty}\left|\frac{\Gamma\left(\frac{1}{2}+\frac{it}{2} \right)}{\Gamma\left(\frac{1}{4}+\frac{it}{4}+\frac{b}{2} \right)}\right|^2\Xi\left(-\frac{t}{2},\chi\right)\Xi\left(\frac{t}{2},\chi\right)\cos\left( \frac{t}{2}\log\alpha\right)dt.
\end{align*}

