Note that up to \eqref{before cauchy}, the calculation holds for any $N\in\mathbb{N}$ and $k\in\mathbb{N}\cup\{0\}$. Thus, letting $N=1$ in \eqref{before cauchy} gives for $-1-k<c<-k$,
\begin{align*}
\mathfrak{F}_{k,1}(x)=(-1)^kx^{k-1}\frac{1}{2\pi i}\int_{(c)}\frac{-\pi\zeta(s+k)\zeta(1-s)}{\sin(\pi s)}x^sds.
\end{align*}
We shift the line of integration to $1<\lambda<2$ in the similar manner as we did in after \eqref{before cauchy}. Thus, we have
\begin{align}\label{cauchy 2}
\mathfrak{F}_{k,1}(x)=(-1)^kx^{k-1}\left(\frac{1}{2\pi i}\int_{(\lambda)}\frac{-\pi\zeta(s+k)\zeta(1-s)}{\sin(\pi s)}x^sds-\mathscr{R}_{k,1}(x)\right).
\end{align}
The calculation of the residues depends on the values of $k$ is $0$, $1$ and $k\geq2$. \\
\textbf{Case I:} When $k=0$, the integrand has double pole at $s=0$ due to $\zeta(1-s)$ and $\sin(\pi s)$ and $s=1$ due to $\zeta(s)$ and $\sin(\pi s)$. The residues at these points are:
\begin{align}\label{k=0}
R_0&=\frac{1}{2}\big(\gamma-\log(2\pi x)\big)\nonumber\\
R_1&=\frac{x}{2}\left(\log\left(\frac{2\pi}{x}\right)-\gamma\right).
\end{align}
\textbf{Case II:} Let $k=1$. Now integrand has simple pole at $s=1,-1$ due to $\sin(\pi s)$ and pole of order three at $s=0$ due to $\sin(\pi s), \zeta(s+1)$ and $\zeta(1-s)$ with residues:
\begin{align}\label{k=1}
R_1&=-\frac{\pi^2}{12}x\nonumber\\
R_{-1}&=\frac{\pi^2}{12}\frac{1}{x}\nonumber\\
R_0&=\frac{1}{6}\left(3\log^2(x)+\pi^2-6\gamma^2-12\gamma_1\right).
\end{align}
\textbf{Case III:} For $k\geq2$, the integrand has pole of order 2 at $s=0$ and $s=1-k$ because of $\sin(\pi s), \zeta(1-s)$ and $\sin(\pi s),\zeta(s+k)$, respectively. It has also simple poles at $s=1,-k$ and $s=-j, 1\leq j\leq k-2$ due to $\sin(\pi s)$. The residues at these poles can be evaluated to 
\begin{align}\label{k>2}
R_0&=\zeta(k)(\log(x)-\gamma)+\zeta'(k)\nonumber\\
R_{1-k}&=(-1)^kx^{1-k}\left\{\zeta(k)(\log(x)+\gamma)-\zeta'(k)\right\}\nonumber\\
R_1&=-\frac{x}{2}\zeta(1+k)\nonumber\\
R_{-k}&=\frac{(-1)^k}{2x^k}\zeta(k+1)\nonumber\\
R_j&=\sum_{j=1}^{k-2}(-1)^{j-1}\zeta(j+1)\zeta(k-j)x^{-j}.
\end{align}
Upon combining the residues from \eqref{k=0}, \eqref{k=1} and \eqref{k>2} together in \eqref{cauchy 2}, we see that $\mathscr{R}_{k,1}(x)$ is nothing but $\mathcal{B}_k(x)$ defined in the statement of the theorem.

The same argument, we used to obtain \eqref{line integral evaluation}, can be adapted to show that
\begin{align*}
\frac{1}{2\pi i}\int_{(\lambda)}\frac{-\pi\zeta(s+k)\zeta(1-s)}{\sin(\pi s)}x^sds=\mathfrak{F}_{k,1}\left(\frac{1}{x}\right).
\end{align*}
Substituting the residues and the above integral in \eqref{cauchy 2}, we complete the proof.

