The first-equality follows by letting $k=0$ in Theorem \ref{2.7}. Now, for the second equality we evaluate
\begin{align*}
\sum_{n=1}^{\infty}\chi(n)\psi(nx,\chi).
\end{align*}
Hence, for $0<c<1,$ from \eqref{xisi} and by employing the reflection formula for the gamma function $\Gamma(s)\Gamma(1-s)=\pi/\sin(\pi s)$ in the second step, we see that
\begin{align*}
\sum_{n=1}^{\infty}\chi(n)\psi(nx,\chi)&=\sum_{n=1}^{\infty}\chi(n)\frac{1}{2\pi i}\int_{(c)}\frac{-\pi L(1-s,\chi)}{\sin(\pi s)}(nx)^{-s}\ ds\\
&=-\frac{1}{2\pi i}\int_{(c)}\Gamma(s)\Gamma(1-s) L(1-s,\chi)L(s,\chi)x^{-s}\ ds.
\end{align*}
Applying the definition \eqref{xi} in the above equation to obtain
\begin{align*}
\sum_{n=1}^{\infty}\chi(n)\psi(nx,\chi)
&=-\frac{1}{2\pi i}\int_{(c)}\frac{\Gamma(s)\Gamma(1-s)}{\Gamma\left(\frac{1-s+b}{2} \right)}\left(\frac{\pi}{d} \right)^{\frac{1-s+b}{2}}\frac{\xi(1-s,\chi)\xi
(s,\chi)}{\Gamma\left(\frac{s+b}{2} \right)}\left(\frac{\pi}{q} \right)^{\frac{s+b}{2}}x^{-s}\ ds.
\end{align*}
Letting $c=\frac{1}{2},$ we see that 
\begin{align*}
\sum_{n=1}^{\infty}\chi(n)\psi(nx,\chi)
&=-\left(\frac{\pi}{d} \right)^{\frac{1}{2}+b}\frac{1}{2\pi i}\int_{\frac{1}{2}-i\infty}^{\frac{1}{2}+i\infty}\frac{\Gamma(s)\Gamma(1-s)}{\Gamma\left(\frac{1-s+b}{2} \right)\Gamma\left(\frac{s+b}{2} \right)}\xi(1-s,\chi)\xi(s,\chi)x^{-s}\ ds.
\end{align*}
Now we perform the change of variable $s=\frac{1}{2}+it$ and employing \eqref{Xi}, 
\begin{align*}
\sum_{n=1}^{\infty}\chi(n)\psi(nx,\chi)
&=-\frac{1}{\sqrt{x}}\left(\frac{\pi}{d} \right)^{\frac{1}{2}+b}\frac{1}{2\pi}\int_{-\infty}^{\infty}\frac{\Gamma\left(\frac{1}{2}+it \right)\Gamma\left(\frac{1}{2}-it \right)}{\Gamma\left(\frac{1}{4}-\frac{it}{2}+\frac{b}{2} \right)\Gamma\left(\frac{1}{4}+\frac{it}{2}+\frac{b}{2} \right)}\Xi(-t,\chi)\Xi(t,\chi)x^{-it}\ dt.
\end{align*}
We perform the change of variable by $t\to t/2$, and after some considerable simplification, we arrive at 
{\allowdisplaybreaks\begin{align*}
&\sum_{n=1}^{\infty}\chi(n)\psi(nx,\chi)\nonumber\\
&=-\frac{1}{2\pi\sqrt{x}}\left(\frac{\pi}{d} \right)^{b+\frac{1}{2}}\int_{0}^{\infty}\frac{\Gamma\left(\frac{1}{2}+\frac{it}{2}  \right)\Gamma\left(\frac{1}{2}-\frac{it}{2} \right)}{\Gamma\left(\frac{1}{4}-\frac{it}{4}+\frac{b}{2} \right)\Gamma\left(\frac{1}{4}+\frac{it}{4}+\frac{b}{2} \right)}\Xi\left(-\frac{t}{2} ,\chi\right)\Xi\left(\frac{t}{2} ,\chi\right)\cos\left(\frac{t \log x}{2}\right)dt.
\end{align*}}
This completes the proof of the theorem.
